mapper.update:
UPDATE member_points
SET total_points = total_points - #{points},
    update_time = NOW()
WHERE user_id = #{userId}
  AND total_points >= #{points}

mapper.select:
SELECT COALESCE(mp.id, 0) AS id, s.id AS userId, COALESCE(mp.total_points, 0) AS totalPoints, mp.create_time AS createTime, mp.update_time AS updateTime, s.username, s.student_no AS studentNo FROM student s LEFT JOIN member_points mp ON mp.user_id = s.id
AND s.username LIKE CONCAT('%', #{username}, '%')
ORDER BY COALESCE(mp.update_time, s.create_time) DESC LIMIT #{offset}, #{pageSize}
